    def spans(seps,n):
        out=[]; cur=None
        for i in range(n+1):
            if i not in seps:
                if cur is None: cur=[i,i]
                else: cur[1]=i
            else:
                if cur: out.append(cur); cur=None
        if cur: out.append(cur)
        return out
    ws=spans(srows,H); wc=spans(scols,W)
